SET NOCOUNT ON;

DECLARE @sql NVARCHAR(MAX) = N'';
DECLARE @workspaceName NVARCHAR(256) = N'Dynatech_MDM_Bronze';

-- Escape workspace name for embedding
SET @workspaceName = REPLACE(@workspaceName, '''', '''''' );

-- Prefix we'll remove at the end
DECLARE @blockPrefix NVARCHAR(50) = N'UNION ALL' + CHAR(13) + CHAR(10);

-- Prepare a temp table with row numbers to iterate without using @@FETCH_STATUS
IF OBJECT_ID('tempdb..#dbs') IS NOT NULL DROP TABLE #dbs;

CREATE TABLE #dbs (
    rn INT PRIMARY KEY,
    database_id INT,
    name SYSNAME
);

INSERT INTO #dbs (rn, database_id, name)
SELECT ROW_NUMBER() OVER (ORDER BY database_id) AS rn,
       database_id,
       name
FROM sys.databases
WHERE state = 0
  AND database_id > 4;   -- exclude system DBs

DECLARE @i INT = 1;
DECLARE @max INT = (SELECT ISNULL(MAX(rn),0) FROM #dbs);

WHILE @i <= @max
BEGIN
    DECLARE @dbName SYSNAME;
    SELECT @dbName = name FROM #dbs WHERE rn = @i;

    BEGIN TRY
        DECLARE @oneBlock NVARCHAR(MAX);

        SET @oneBlock =
            @blockPrefix + N'
SELECT ' + QUOTENAME(@workspaceName,'''') + N' AS WorkspaceName,
       ' + QUOTENAME(@dbName,'''') + N' AS DatabaseName,
       t.TABLE_SCHEMA AS SchemaName,
       t.TABLE_NAME AS TableName
FROM ' + QUOTENAME(@dbName) + N'.INFORMATION_SCHEMA.TABLES t
WHERE t.TABLE_TYPE = ''BASE TABLE''';

        SET @sql = @sql + @oneBlock;
    END TRY
    BEGIN CATCH
        -- Log and continue if a DB is inaccessible or errors
        PRINT 'Skipped DB: ' + ISNULL(@dbName,'<unknown>') + ' - ' + ERROR_MESSAGE();
    END CATCH

    SET @i = @i + 1;
END

DROP TABLE #dbs;

-- If nothing appended, exit
IF LEN(@sql) = 0
BEGIN
    PRINT 'No accessible user databases found or none with base tables.';
    RETURN;
END

-- Remove the initial 'UNION ALL' safely
SET @sql = STUFF(@sql, 1, LEN(@blockPrefix), N'');  

-- Optional: inspect the generated SQL (comment out in production)
PRINT @sql;

-- Execute the generated query
EXEC sp_executesql @sql;
